1	"use client";
2	
3	/**
4	 * PREVIEW TEMPLATE — Domains landing (Direction: "Register + transfer").
5	 *
6	 * Hero centerpiece = an animated domain-search widget in a premium glass frame:
7	 * it auto-types a brandable name, runs a "checking" scan, then reveals the exact
8	 * result plus a TLD price grid that populates row-by-row. The visitor can also
9	 * type their own name and get an instant (mocked) availability read — so the hero
10	 * doubles as a working-looking search, which is the whole buying trigger.
11	 *
12	 * Below the hero: the "everything in one account" bundling story (domain +
13	 * hosting + email on one bill), a transfer + managed-DNS section that reuses the
14	 * real <DnsManager/> showcase screen, a TLD pricing rail, and compact 5-star
15	 * reviews. Asymmetric/editorial throughout — never a centered stack.
16	 *
17	 * Net-new, preview-only. Touches no live page or shared component (imports the
18	 * shared DnsManager + gamelanding kit read-only; reuse, not edits).
19	 */
20	
21	import Link from "next/link";
22	import { useEffect, useMemo, useState } from "react";
23	import styles from "./domains.module.css";
24	import {
25	  DEMO_QUERY,
26	  DEMO_TLDS,
27	  PRICING_TLDS,
28	  DOMAIN_REVIEWS,
29	  RATING_AVG,
30	  RATING_LABEL,
31	} from "./data";
32	import { POPULAR_TLDS } from "@/components/marketing/tlds";
33	import { DnsManager } from "@/components/marketing/showcase/DnsManager";
34	import { usePrefersReducedMotion, useInViewOnce, StarRow } from "@/components/marketing/gamelanding/kit";
35	import {
36	  IconArrow,
37	  IconCheck,
38	  IconGlobe,
39	  IconMail,
40	  IconServer,
41	  IconLock,
42	  IconBolt,
43	  IconNetwork,
44	  IconClock,
45	} from "@/components/marketing/icons";
46	
47	type Phase = "typing" | "checking" | "results";
48	type Mode = "demo" | "user";
49	type ResultRow = { domain: string; tld: string; available: boolean; price: string; premium?: boolean };
50	
51	function money(cents: number): string {
52	  return `$${(cents / 100).toFixed(2)}`;
53	}
54	
55	/** Deterministic pseudo-availability so user-typed names read realistically. */
56	function avail(name: string, tld: string): boolean {
57	  let h = 5381;
58	  const s = `${name.toLowerCase()}.${tld}`;
59	  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
60	  return h % 4 !== 0; // ~75% available
61	}
62	
63	function buildResults(name: string, mode: Mode): { exact: ResultRow; rows: ResultRow[] } {
64	  if (mode === "demo") {
65	    const rows: ResultRow[] = DEMO_TLDS.map((t) => ({
66	      domain: `${name}${t.tld}`,
67	      tld: t.tld,
68	      available: t.available,
69	      price: t.price,
70	      premium: t.premium,
71	    }));
72	    return { exact: rows[0], rows: rows.slice(1) };
73	  }
74	  const rows: ResultRow[] = POPULAR_TLDS.slice(0, 6).map((t) => ({
75	    domain: `${name}${t.tld}`,
76	    tld: t.tld,
77	    available: avail(name, t.tld.replace(/^\./, "")),
78	    price: money(t.fromCents),
79	  }));
80	  const exact = rows.find((r) => r.tld === ".com") ?? rows[0];
81	  return { exact, rows: rows.filter((r) => r !== exact) };
82	}
83	
84	/* ── The animated search widget (hero centerpiece) ───────────────────────── */
85	function DomainSearchPanel() {
86	  const reduced = usePrefersReducedMotion();
87	  const [q, setQ] = useState("");
88	  const [phase, setPhase] = useState<Phase>("typing");
89	  const [mode, setMode] = useState<Mode>("demo");
90	
91	  // Auto-demo loop (only while untouched). Reduced motion → rest on the result state.
92	  useEffect(() => {
93	    if (mode !== "demo") return;
94	    if (reduced) {
95	      setQ(DEMO_QUERY);
96	      setPhase("results");
97	      return;
98	    }
99	    let cancelled = false;
100	    const timers: ReturnType<typeof setTimeout>[] = [];
101	    const run = () => {
102	      if (cancelled) return;
103	      setQ("");
104	      setPhase("typing");
105	      let i = 0;
106	      const typeNext = () => {
107	        if (cancelled) return;
108	        i += 1;
109	        setQ(DEMO_QUERY.slice(0, i));
110	        if (i < DEMO_QUERY.length) {
111	          timers.push(setTimeout(typeNext, 78));
112	        } else {
113	          setPhase("checking");
114	          timers.push(
115	            setTimeout(() => {
116	              if (cancelled) return;
117	              setPhase("results");
118	              timers.push(setTimeout(() => run(), 4200));
119	            }, 950),
120	          );
121	        }
122	      };
123	      timers.push(setTimeout(typeNext, 650));
124	    };
125	    run();
126	    return () => {
127	      cancelled = true;
128	      timers.forEach(clearTimeout);
129	    };
130	  }, [mode, reduced]);
131	
132	  // User-mode: brief "checking" then results.
133	  useEffect(() => {
134	    if (mode !== "user") return;
135	    if (q.trim().length < 2) {
136	      setPhase("typing");
137	      return;
138	    }
139	    setPhase("checking");
140	    const t = setTimeout(() => setPhase("results"), 480);
141	    return () => clearTimeout(t);
142	  }, [q, mode]);
143	
144	  const name = (q.trim().toLowerCase() || DEMO_QUERY).replace(/\s+/g, "");
145	  const { exact, rows } = useMemo(() => buildResults(name, mode), [name, mode]);
146	  const showResults = phase === "results" && (mode === "demo" || q.trim().length >= 2);
147	
148	  return (
149	    <div className="relative">
150	      {/* focus glow ring */}
151	      <div
152	        className="pointer-events-none absolute -inset-[1.5px] rounded-[26px] bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-70 blur-lg"
153	        aria-hidden
154	      />
155	      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/85 p-4 shadow-2xl shadow-black/50 backdrop-blur-xl sm:p-5">
156	        {/* aura */}
157	        <div
158	          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
159	          style={{ background: "radial-gradient(45% 45% at 85% 0%, rgba(34,211,238,0.18), transparent 70%)" }}
160	          aria-hidden
161	        />
162	        <div className="mb-3 flex items-center justify-between">
163	          <span className="inline-flex items-center gap-2 text-[12px] font-medium text-slate-300">
164	            <IconGlobe size={14} />
165	            Domain search
166	          </span>
167	          <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
168	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
169	            instant
170	          </span>
171	        </div>
172	
173	        {/* search field */}
