3	/**
4	 * SEA LATENCY MAP — the location template's signature visual.
5	 *
6	 * A regional, Singapore-centred take on the shipped <NetworkMap/>: SEA landmass
7	 * rendered as deterministic dot clusters (SSR-safe, no assets), Singapore as a
8	 * pulsing origin node, and brand-gradient arcs to six nearby metros. Each arc
9	 * carries a travelling "ping" pulse and each city node shows a LIVE latency
10	 * readout that counts up on first view and idles with small jitter — telling the
11	 * "low-latency across Asia" story with real numbers, not a spinning globe.
12	 *
13	 * All motion is disabled under prefers-reduced-motion (inline <style> guard +
14	 * the shared kit hooks resolve to their resting values). Net-new, preview-only.
15	 */
16	
17	import { CITIES, SINGAPORE, type LatencyCity } from "./data";
18	import { usePrefersReducedMotion, useInViewOnce, useCountUp, useJitter } from "@/components/marketing/gamelanding/kit";
19	
20	const W = 1000;
21	const H = 600;
22	
23	/* SEA landmass footprints on the viewBox (decorative, equirectangular-ish). */
24	const LAND: { cx: number; cy: number; rx: number; ry: number }[] = [
25	  { cx: 205, cy: 150, rx: 135, ry: 110 }, // mainland SEA (Thailand/Vietnam/Cambodia)
26	  { cx: 350, cy: 60, rx: 170, ry: 70 }, // south China coast + Hong Kong
27	  { cx: 224, cy: 250, rx: 34, ry: 90 }, // Malay peninsula
28	  { cx: 205, cy: 312, rx: 78, ry: 34 }, // Sumatra
29	  { cx: 322, cy: 292, rx: 72, ry: 60 }, // Borneo
30	  { cx: 300, cy: 348, rx: 96, ry: 22 }, // Java
31	  { cx: 452, cy: 178, rx: 46, ry: 74 }, // Philippines
32	  { cx: 860, cy: 540, rx: 140, ry: 96 }, // Australia (NE)
33	];
34	
35	const noise = (i: number, j: number) => {
36	  const s = Math.sin(i * 12.9898 + j * 78.233) * 43758.5453;
37	  return s - Math.floor(s);
38	};
39	
40	function landDots() {
41	  const dots: { x: number; y: number; o: number }[] = [];
42	  const step = 14;
43	  for (let x = step; x < W; x += step) {
44	    for (let y = 24; y < H - 16; y += step) {
45	      let best = 2;
46	      for (const c of LAND) {
47	        const t = ((x - c.cx) / c.rx) ** 2 + ((y - c.cy) / c.ry) ** 2;
48	        if (t < best) best = t;
49	      }
50	      const n = noise(x, y);
51	      if (best < 0.9 || (best < 1 && n > 0.55)) {
52	        dots.push({ x: x + (n - 0.5) * 4, y: y + (noise(y, x) - 0.5) * 4, o: 0.2 + (1 - best) * 0.28 });
53	      }
54	    }
55	  }
56	  return dots;
57	}
58	
59	const arcPath = (a: { x: number; y: number }, b: { x: number; y: number }) => {
60	  const mx = (a.x + b.x) / 2;
61	  const my = (a.y + b.y) / 2 - Math.hypot(a.x - b.x, a.y - b.y) * 0.24;
62	  return `M${a.x},${a.y} Q${mx},${my} ${b.x},${b.y}`;
63	};
64	
65	const TIER_COLOR: Record<LatencyCity["tier"], string> = {
66	  excellent: "#22d3ee",
67	  great: "#3b82f6",
68	  good: "#8a70fb",
69	};
70	
71	export function SeaLatencyMap() {
72	  const dots = landDots();
73	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
74	
75	  return (
76	    <div
77	      ref={ref}
78	      className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-950/70 glow-brand"
79	    >
80	      <style>{`
81	        @keyframes lat-pulse { 0%{offset-distance:0%;opacity:0} 10%{opacity:1} 85%{opacity:1} 100%{offset-distance:100%;opacity:0} }
82	        @keyframes lat-blip { 0%,100%{opacity:.55;r:3} 50%{opacity:1;r:3.6} }
83	        @keyframes lat-ring { 0%{transform:scale(.6);opacity:.55} 100%{transform:scale(1.9);opacity:0} }
84	        @media (prefers-reduced-motion: reduce){
85	          .lat-pulse,.lat-blip,.lat-ring{animation:none!important}
86	          .lat-pulse{opacity:0}
87	        }
88	      `}</style>
89	
90	      {/* header */}
91	      <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5 font-mono text-[11px]">
92	        <span className="flex items-center gap-2 text-slate-400">
93	          <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> nxeon · singapore edge
94	        </span>
95	        <span className="text-slate-500">live round-trip · 6 SEA metros</span>
96	      </div>
97	
98	      <div className="relative">
99	        <div
100	          aria-hidden
101	          className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_28%_44%,rgba(34,211,238,0.12),transparent_62%)]"
102	        />
103	        <svg
104	          viewBox={`0 0 ${W} ${H}`}
105	          className="relative block w-full"
106	          role="img"
107	          aria-label="Latency from Nxeon Singapore to Kuala Lumpur, Jakarta, Bangkok, Hong Kong, Manila and Sydney"
108	        >
109	          <defs>
110	            <linearGradient id="lat-arc" x1="0" y1="0" x2="1" y2="0">
111	              <stop offset="0%" stopColor="#22d3ee" />
112	              <stop offset="100%" stopColor="#8a70fb" />
113	            </linearGradient>
114	            <radialGradient id="lat-sg" cx="50%" cy="50%" r="50%">
115	              <stop offset="0%" stopColor="#67e8f9" />
116	              <stop offset="100%" stopColor="#22d3ee" />
117	            </radialGradient>
118	          </defs>
119	
120	          {/* landmass dots */}
121	          {dots.map((d, i) => (
122	            <circle key={i} cx={d.x} cy={d.y} r={1.15} fill={`rgba(120,150,220,${d.o})`} />
123	          ))}
124	
125	          {/* arcs + travelling ping pulses */}
126	          {CITIES.map((c, k) => {
127	            const d = arcPath(SINGAPORE, c);
128	            return (
129	              <g key={`arc-${c.id}`}>
130	                <path d={d} fill="none" stroke="url(#lat-arc)" strokeWidth="1.3" opacity="0.45" />
131	                <circle
132	                  className="lat-pulse"
133	                  r="3"
134	                  fill={TIER_COLOR[c.tier]}
135	                  style={{
136	                    offsetPath: `path('${d}')`,
137	                    animation: seen ? `lat-pulse ${2.6 + k * 0.28}s ${k * 0.32}s linear infinite` : "none",
138	                    opacity: 0,
139	                  }}
140	                />
141	              </g>
142	            );
143	          })}
144	
145	          {/* city nodes with live readouts */}
146	          {CITIES.map((c) => (
147	            <CityNode key={c.id} city={c} active={seen} />
148	          ))}
149	
150	          {/* Singapore origin node */}
151	          <g>
152	            <circle className="lat-ring" cx={SINGAPORE.x} cy={SINGAPORE.y} r="14" fill="none" stroke="#22d3ee" strokeWidth="1.5" style={{ transformOrigin: `${SINGAPORE.x}px ${SINGAPORE.y}px`, animation: seen ? "lat-ring 2.6s ease-out infinite" : "none" }} />
153	            <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r="16" fill="rgba(34,211,238,0.12)" />
154	            <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r="5.2" fill="url(#lat-sg)" />
155	            <g transform={`translate(${SINGAPORE.x - 4}, ${SINGAPORE.y + 16})`}>
156	              <rect x="0" y="0" width="118" height="22" rx="11" fill="rgba(6,10,20,0.92)" stroke="rgba(34,211,238,0.4)" />
157	              <circle cx="13" cy="11" r="3" fill="#22d3ee" />
158	              <text x="24" y="15" fontFamily="ui-monospace,monospace" fontSize="11" fontWeight="600" fill="#e2e8f0">
159	                Singapore · you
160	              </text>
161	            </g>
162	          </g>
163	        </svg>
164	      </div>
165	    </div>
166	  );
167	}
168	
169	/* one city node — animated ms readout riding the map */
170	function CityNode({ city, active }: { city: LatencyCity; active: boolean }) {
171	  const reduced = usePrefersReducedMotion();
172	  const base = useCountUp(city.ms, active, 1200, reduced);
173	  const live = useJitter(city.ms, city.swing, active, 2200, reduced);
174	  const value = base < city.ms ? base : live; // count up, then idle-jitter
175	  const color = TIER_COLOR[city.tier];
176	  const labelW = city.name.length * 6.4 + 52;
177	  // keep labels inside the viewBox
178	  const flip = city.x + labelW + 16 > W;
179	  const lx = flip ? -labelW - 10 : 12;
180	
181	  return (
182	    <g>
183	      <circle cx={city.x} cy={city.y} r="10" fill="rgba(34,211,238,0.08)" />
184	      <circle
185	        className="lat-blip"
186	        cx={city.x}
187	        cy={city.y}
188	        r="3"
189	        fill={color}
190	        style={{ animation: active && !reduced ? "lat-blip 2.4s ease-in-out infinite" : "none" }}
191	      />
192	      <g transform={`translate(${city.x + lx}, ${city.y - 11})`}>
193	        <rect x="0" y="0" width={labelW} height="22" rx="11" fill="rgba(6,10,20,0.9)" stroke="rgba(255,255,255,0.1)" />
194	        <text x="9" y="15" fontFamily="ui-monospace,monospace" fontSize="10.5" fill="#cbd5e1">
195	          {city.name}
196	        </text>
197	        <text
198	          x={labelW - 8}
199	          y="15"
200	          textAnchor="end"
201	          fontFamily="ui-monospace,monospace"
202	          fontSize="10.5"
203	          fontWeight="700"
204	          fill={color}
205	        >
206	          {value}ms
207	        </text>
208	      </g>
209	    </g>
210	  );
211	}
