4	
5	/**
6	 * Third-party review badges (Trustpilot · HostAdvice · Google) for the hero.
7	 *
8	 * REAL DATA, WITH AN HONEST FALLBACK (2026-08-10). This component now reads the
9	 * live Reviews engine:
10	 *
11	 *   - It aggregates APPROVED reviews by external source (Google/Trustpilot/
12	 *     HostAdvice) into a real average score and count, and links each badge to
13	 *     the review-profile URL configured in /admin/reviews.
14	 *   - A source is only shown as a REAL badge when it has ≥1 approved review AND a
15	 *     configured profile URL — so we never render a live-looking badge that links
16	 *     nowhere or is backed by nothing.
17	 *   - When NO source qualifies (the normal pre-launch state), it falls back to the
18	 *     clearly-labelled DEMO PLACEHOLDER below, so the hero never looks empty.
19	 *
20	 * ⚠️ DEMO PLACEHOLDER — the scores/counts in `DEMO_BADGES` are NOT real review
21	 * data. They exist only so the hero has something to show before real reviews are
22	 * approved. They are never mixed with real data: the moment one real external
23	 * review exists, the whole strip switches to real badges only. Do not publish
24	 * these figures as genuine — collect real reviews (they'll appear automatically).
25	 */
26	
27	type Badge = { name: string; score: string; count: string; href: string; star: string; google?: boolean };
28	
29	const DEMO_BADGES: Badge[] = [
30	  { name: "Trustpilot", score: "4.9", count: "312", href: "#", star: "#00b67a" },
31	  { name: "HostAdvice", score: "4.8", count: "148", href: "#", star: "#f5a623" },
32	  { name: "Google", score: "4.9", count: "205", href: "#", star: "#fbbc05", google: true },
33	];
34	
35	const SOURCE_META: Record<string, { name: string; star: string; google?: boolean; urlKey: string }> = {
36	  TRUSTPILOT: { name: "Trustpilot", star: "#00b67a", urlKey: "review_url_trustpilot" },
37	  HOSTADVICE: { name: "HostAdvice", star: "#f5a623", urlKey: "review_url_hostadvice" },
38	  GOOGLE: { name: "Google", star: "#fbbc05", google: true, urlKey: "review_url_google" },
39	};
40	
41	function Stars({ color }: { color: string }) {
42	  return (
43	    <span style={{ color }} className="text-[13px] leading-none tracking-tight" aria-hidden>
44	      ★★★★★
45	    </span>
46	  );
47	}
