2	import { currentUser } from "@/lib/auth";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { registrarConfigured } from "@/lib/registrar";
5	import { checkAvailabilityBatched, type DomainResult } from "@/lib/tools/domain-availability";
6	import { SEARCH_TLDS } from "@/components/marketing/tlds";
7	import { trustedClientIp } from "@/app/api/_lib/client-ip";
