9	export const dynamic = "force-dynamic";
10	
11	/**
12	 * Exact-domain search behind both the marketing DomainChecker and the signed-in
13	 * dashboard DomainSearch.
14	 *
15	 * The old handler had two money-losing defects, both fixed here:
16	 *
17	 *   1. It hardcoded a tiny extension list (com/net/io/dev…) and, for a full
18	 *      domain like `mahaskitchen.in`, only ever offered .com/.net/.io/.dev as
19	 *      alternatives — a registrable, available `.in` was never surfaced.
20	 *   2. It DROPPED every unavailable result (`filter(priceCents !== null)`), so a
21	 *      taken exact match simply vanished instead of being shown as "Taken".
22	 *
23	 * Now:
24	 *   - The EXACT typed domain (when the query is a full domain) is always checked
25	 *     and returned first as `exact`, whatever its TLD — the registrar prices
26	 *     arbitrary TLDs.
27	 *   - The base name is checked across a BROAD catalog (SEARCH_TLDS, ~two dozen),
28	 *     and taken / unknown results are RETURNED, clearly statused, not hidden.
29	 *   - Availability goes through the shared batched+cached+globally-throttled
30	 *     `checkAvailabilityBatched`, so the whole extension list is ONE upstream
31	 *     call to the metered registrar, and prices are only ever the real ones it
32	 *     returned.
33	 */
34	
35	type CheckStatus = "available" | "taken" | "unknown";
36	
37	type CheckItem = {
38	  domain: string;
39	  sld: string;
40	  tld: string;
41	  status: CheckStatus;
42	  /** Convenience mirror of `status === "available"` for older callers. */
43	  available: boolean;
44	  premium: boolean;
45	  priceCents: number | null;
46	  renewCents: number | null;
47	};
48	
49	/** Cap so the base name + its extensions fit a SINGLE batched registrar call. */
50	const MAX_CANDIDATES = 24;
51	
52	function splitDomain(domain: string): { sld: string; tld: string } {
53	  const dot = domain.indexOf(".");
54	  return dot > 0 ? { sld: domain.slice(0, dot), tld: domain.slice(dot + 1) } : { sld: domain, tld: "" };
55	}
56	
57	function toItem(r: DomainResult): CheckItem {
58	  const { sld, tld } = splitDomain(r.domain);
59	  return {
60	    domain: r.domain,
61	    sld,
62	    tld,
63	    status: r.status,
64	    available: r.status === "available",
65	    premium: r.premium,
66	    priceCents: r.priceCents,
67	    renewCents: r.renewCents,
68	  };
69	}
70	
71	const unknownItem = (domain: string): CheckItem => ({
72	  domain,
73	  ...splitDomain(domain),
74	  status: "unknown",
75	  available: false,
76	  premium: false,
77	  priceCents: null,
78	  renewCents: null,
79	});
80	
81	export async function GET(req: NextRequest) {
82	  const user = await currentUser();
83	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
84	
85	  // One search fans out to the registrar (one batched upstream call) — throttle
86	  // per-IP so a customer can't grind the metered registrar.
87	  const rl = checkRateLimit(`domcheck:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
88	  if (!rl.ok) {
89	    return NextResponse.json(
90	      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
91	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
92	    );
93	  }
94	
95	  const q = (req.nextUrl.searchParams.get("q") ?? "").toLowerCase().trim().replace(/[^a-z0-9.-]/g, "");
96	  if (q.length < 2) return NextResponse.json({ results: [] });
97	  if (!registrarConfigured()) {
98	    return NextResponse.json({ configured: false, results: [] });
99	  }
100	
101	  // A query is a full domain when it has a dot with a non-empty label on each
102	  // side (the right side being a plausible TLD, 2+ chars). We keep the EXACT
103	  // string typed — including its TLD — and never silently drop it.
104	  const dot = q.indexOf(".");
105	  const base = dot > 0 ? q.slice(0, dot) : q;
106	  const typedTld = dot > 0 ? q.slice(dot + 1) : "";
107	  const exactDomain = dot > 0 && base.length >= 1 && typedTld.length >= 2 ? q : null;
108	
109	  // Build the candidate list: the exact typed domain first (primary), then the
110	  // base name across the broad catalog, de-duplicated, capped to one batch.
111	  const seen = new Set<string>();
112	  const candidates: string[] = [];
113	  if (exactDomain) {
114	    candidates.push(exactDomain);
115	    seen.add(exactDomain);
116	  }
117	  if (base.length >= 1) {
118	    for (const tld of SEARCH_TLDS) {
119	      if (candidates.length >= MAX_CANDIDATES) break;
120	      const d = `${base}.${tld}`;
121	      if (seen.has(d)) continue;
122	      seen.add(d);
123	      candidates.push(d);
124	    }
125	  }
126	  if (candidates.length === 0) return NextResponse.json({ configured: true, results: [] });
127	
128	  // ONE batched, cached, globally-throttled registrar lookup for the whole list.
129	  const outcome = await checkAvailabilityBatched(candidates);
130	  const byDomain = new Map(outcome.results.map((r) => [r.domain.toLowerCase(), r]));
131	  const itemFor = (d: string): CheckItem => {
132	    const r = byDomain.get(d.toLowerCase());
133	    return r ? toItem(r) : unknownItem(d);
134	  };
135	
136	  // `results` is the COMPLETE list (including the exact typed domain) so callers
137	  // that look a specific name up in it — e.g. the register wizard's re-check —
138	  // still find it. `exact` is a pointer to that same primary entry; the display
139	  // components render it prominently and drop it from the alternatives list.
140	  const exact = exactDomain ? itemFor(exactDomain) : null;
141	  const results = candidates.map(itemFor);
142	
143	  return NextResponse.json({
144	    configured: outcome.configured,
145	    throttled: outcome.throttled,
146	    query: q,
147	    exact,
148	    results,
149	  });
150	}
