type Phase = "typing" | "checking" | "results";
type Mode = "demo" | "user";
type ResultRow = { domain: string; tld: string; available: boolean; price: string; premium?: boolean };
type Built = { exact: ResultRow; rows: ResultRow[] };

/** Subset of the real /api/domains/check response this widget consumes. */
type CheckItem = {
  domain: string;
  tld: string;
  status: "available" | "taken" | "unknown";
  premium?: boolean;
  priceCents: number | null;
};
type CheckResponse = {
  configured?: boolean;
  exact?: CheckItem | null;
  results?: CheckItem[];
};

function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** Deterministic pseudo-availability so user-typed names read realistically. */
function avail(name: string, tld: string): boolean {
  let h = 5381;
  const s = `${name.toLowerCase()}.${tld}`;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h % 4 !== 0; // ~75% available
}

/** The canned hero demo — the curated DEMO_TLDS, exact result first. */
function buildDemo(): Built {
  const rows: ResultRow[] = DEMO_TLDS.map((t) => ({
    domain: `${DEMO_QUERY}${t.tld}`,
    tld: t.tld,
    available: t.available,
    price: t.price,
    premium: t.premium,
  }));
  return { exact: rows[0], rows: rows.slice(1) };
}

/**
 * Deterministic client-side availability read — the graceful fallback when the
 * live registrar check isn't reachable from a preview (e.g. logged-out visitor,
 * registrar not yet configured). Same UX as a live result: an exact primary plus
 * available/taken alternatives, priced from the static catalog.
 */
function buildDeterministic(query: string): Built {
  const clean = query.toLowerCase().replace(/\s+/g, "");
  const dot = clean.indexOf(".");
  const base = (dot > 0 ? clean.slice(0, dot) : clean) || DEMO_QUERY;
  const typedTld = dot > 0 ? clean.slice(dot) : ""; // includes leading dot

  const rows: ResultRow[] = POPULAR_TLDS.slice(0, 6).map((t) => ({
    domain: `${base}${t.tld}`,
    tld: t.tld,
    available: avail(base, t.tld.replace(/^\./, "")),
    price: money(t.fromCents),
  }));

  let exact: ResultRow;
  if (typedTld) {
    const fromCents = POPULAR_TLDS.find((t) => t.tld === typedTld)?.fromCents ?? 1299;
    exact = {
      domain: `${base}${typedTld}`,
      tld: typedTld,
      available: avail(base, typedTld.replace(/^\./, "")),
      price: money(fromCents),
    };
  } else {
    exact = rows.find((r) => r.tld === ".com") ?? rows[0];
  }
  return { exact, rows: rows.filter((r) => r.domain !== exact.domain).slice(0, 6) };
}

/** Map a live /api/domains/check payload into the widget's display shape. */
function buildFromApi(data: CheckResponse): Built | null {
  const items = Array.isArray(data.results) ? data.results : [];
  if (items.length === 0) return null;
  const toRow = (it: CheckItem): ResultRow => ({
    domain: it.domain,
    tld: it.tld ? `.${it.tld}` : "",
    available: it.status === "available",
    price: it.priceCents != null ? money(it.priceCents) : "—",
    premium: !!it.premium,
  });
  const all = items.map(toRow);
  const exact = data.exact ? toRow(data.exact) : (all.find((r) => r.tld === ".com") ?? all[0]);
  return { exact, rows: all.filter((r) => r.domain !== exact.domain).slice(0, 6) };
}

/**
 * Look a query up against the real registrar endpoint, falling back to the
 * deterministic read whenever that isn't usable from a preview (401 for a
 * logged-out visitor, `configured: false`, rate-limited, or a network error).
 * Always resolves to a result so the field returns something per query.
 */
async function lookup(query: string, signal: AbortSignal): Promise<Built> {
  try {
    const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, { signal });
    if (res.ok) {
      const data: CheckResponse = await res.json();
      if (data.configured !== false) {
        const built = buildFromApi(data);
        if (built) return built;
      }
    }
  } catch {
    /* logged-out / offline / aborted → fall through to the deterministic read */
  }
  return buildDeterministic(query);
}

