    }
    let cancelled = false;
    const timers: ReturnType<typeof setTimeout>[] = [];
    setQ("");
    setPhase("typing");
    let i = 0;
    const typeNext = () => {
      if (cancelled) return;
      i += 1;
      setQ(DEMO_QUERY.slice(0, i));
      if (i < DEMO_QUERY.length) {
        timers.push(setTimeout(typeNext, 78));
      } else {
        setPhase("checking");
        timers.push(
          setTimeout(() => {
            if (cancelled) return;
            setPhase("results"); // rest here — the field is now the visitor's
          }, 950),
        );
      }
    };
    timers.push(setTimeout(typeNext, 650));
    return () => {
      cancelled = true;
      timers.forEach(clearTimeout);
    };
  }, [mode, reduced]);

  // User-mode: debounce, then check the real endpoint (deterministic fallback).
  useEffect(() => {
    if (mode !== "user") return;
    const query = q.trim().toLowerCase();
    if (query.length < 2) {
      setPhase("typing");
      setUserResult(null);
      return;
    }
    setPhase("checking");
    const ac = new AbortController();
    let cancelled = false;
    const t = setTimeout(async () => {
      const built = await lookup(query, ac.signal);
      if (cancelled) return;
      setUserResult(built);
      setPhase("results");
    }, 460);
    return () => {
      cancelled = true;
      ac.abort();
      clearTimeout(t);
    };
  }, [q, mode]);

  const demo = useMemo(() => buildDemo(), []);
  const active: Built | null = mode === "user" ? userResult : demo;
  const showResults =
    phase === "results" && active != null && (mode === "demo" || q.trim().length >= 2);
  const exact = active?.exact;
  const rows = active?.rows ?? [];

