import type { Metadata } from "next";
import { DomainsLanding } from "@/components/marketing/domainstemplate/DomainsLanding";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
export const metadata: Metadata = {
  title: "Preview · Domains landing",
  description:
    "Search live domain availability, register or transfer, then point it at your Nxeon VPS with managed DNS — domain, hosting and email on one account, one bill.",
  robots: { index: false, follow: false },
};

const FAQ = [
  {
    q: "Can I check a domain right here?",
    a: "Yes. The hero search runs a one-time demo, then hands you the field — type any name and it returns live availability across 25+ extensions, with an instant deterministic read as a fallback when a live check isn't reachable.",
  },
  {
    q: "Is WHOIS privacy included?",
    a: "Free WHOIS privacy is included for the life of every eligible domain, so your personal contact details stay off the public record.",
  },
  {
    q: "Can I point a domain at my VPS?",
    a: "In one click. The domain lands in the same account as your server and inbox, so DNS is pre-pointed and managed — A, AAAA, CNAME, MX, TXT and SRV records from one clean panel.",
  },
  {
    q: "How do transfers work?",
    a: "Unlock the domain at your current registrar, paste the EPP/auth code, and confirm. Existing records are preserved so mail and sites never blink.",
  },
];

export default function Page() {
  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Domains"
        description="Register or transfer domains with free WHOIS privacy and managed DNS, on the same account as your VPS, hosting and email."
        url={`${APP_URL}/domains`}
        offers={POPULAR_TLDS.map((t) => ({ name: `${t.tld} domain`, price: t.fromCents / 100 }))}
      />
      <FaqJsonLd items={FAQ} />
      <DomainsLanding reviewBadges={<ReviewBadges />} />
    </>
  );
}

