import type { Metadata } from "next";
import { LocationLanding } from "@/components/marketing/locationtemplate/LocationLanding";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { PLANS } from "@/components/marketing/locationtemplate/data";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
export const metadata: Metadata = {
  title: "Preview · Singapore location page",
  description:
    "Host in Singapore, serve all of Southeast Asia. Cloud VPS and game servers on enterprise NVMe in Asia's densest interconnection hub — most of the region inside ~40 ms.",
  robots: { index: false, follow: false },
};

const FAQ = [
  {
    q: "How fast is Singapore to the rest of Southeast Asia?",
    a: "Typical round-trip latency is single digits to Kuala Lumpur and Jakarta, and under ~40 ms to Bangkok, Hong Kong and Manila. Because SEA networks peer locally in Singapore, traffic stays in Asia rather than detouring via the US.",
  },
  {
    q: "What can I deploy in the Singapore region?",
    a: "Cloud VPS and game servers, all provisioned on enterprise NVMe in the Singapore (SGP) region, with always-on DDoS filtering and full root access.",
  },
  {
    q: "Why Singapore specifically?",
    a: "Singapore is where the region physically connects — 15+ subsea cables land there and every major regional network peers in-country, making it Southeast Asia's cable and interconnection crossroads.",
  },
  {
    q: "How quickly does a server come online?",
    a: "Pick Singapore, pick a size, deploy — instances are provisioned and connect-ready in about 47 seconds.",
  },
];

const price = (s: string) => Number(s.replace(/[^0-9.]/g, ""));

export default function Page() {
  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Singapore VPS & Game Servers"
        description="Cloud VPS and game servers deployed in the Singapore (SGP) region on enterprise NVMe, with always-on DDoS filtering and low-latency reach across Southeast Asia."
        url={`${APP_URL}/vps`}
        offers={PLANS.map((p) => ({ name: `${p.tier} · ${p.headline} (Singapore)`, price: price(p.price) }))}
      />
      <FaqJsonLd items={FAQ} />
      <LocationLanding reviewBadges={<ReviewBadges />} />
    </>
  );
}

